import { describe, expect, test } from "vitest";
import type { Breakpoint } from "../../../lib/breakpoints.ts";
import { renderRuntime } from "./runtime.ts";

const FIXTURE: Breakpoint[] = [
  { name: "sm", minWidth: "480px" },
  { name: "md", minWidth: "768px" },
];

describe("renderRuntime", () => {
  test("starts with the AUTOGENERATED banner", () => {
    expect(renderRuntime(FIXTURE).split("\n")[0]).toBe(
      "// AUTOGENERATED by gen-react. Do not edit.",
    );
  });

  test("emits a RESPONSIVE_KEYS tuple prefixed with `base`", () => {
    expect(renderRuntime(FIXTURE)).toContain(
      `const RESPONSIVE_KEYS = ["base", "sm", "md"] as const;`,
    );
  });

  test("exports `Responsive<T>` for wrappers to consume", () => {
    expect(renderRuntime(FIXTURE)).toContain(
      "export type Responsive<T> = T | Partial<Record<Breakpoint, T>>;",
    );
  });

  test("emits a matchMedia query per non-base breakpoint", () => {
    const out = renderRuntime(FIXTURE);
    expect(out).toContain(`sm: "(min-width: 480px)",`);
    expect(out).toContain(`md: "(min-width: 768px)",`);
  });

  test("exports the `responsiveDataAttrs` helper used by every wrapper root", () => {
    expect(renderRuntime(FIXTURE)).toContain("export function responsiveDataAttrs(");
  });

  test("exports the `asElement` widener used by polymorphic-`as` wrappers", () => {
    expect(renderRuntime(FIXTURE)).toContain("export function asElement(");
  });

  test("renders identically on repeated calls", () => {
    expect(renderRuntime(FIXTURE)).toBe(renderRuntime(FIXTURE));
  });
});
